sys_script_include.script:
function WaitForStateChange(grRecord,nSleepForSeconds,nTimeoutSeconds)
{
	if (IsValidRecord(grRecord) == false)
	{
		return false;
	}

	nSleepForSeconds = GetIntegerValue(nSleepForSeconds);
	if (nSleepForSeconds < 1)
	{
		nSleepForSeconds = 1;
	}
	nTimeoutSeconds = GetIntegerValue(nTimeoutSeconds);

	var stopwatch = new StopWatch();
	stopwatch.Start();

	var nCurrentState = GetIntegerValue(grRecord.getValue('state'));
	var nState = nCurrentState;

	while (nCurrentState != nState)
	{
		if (nTimeoutSeconds > 0)
		{
			if (stopwatch.GetSeconds() > nTimeoutSeconds)
			{
				return false;	
			}
		}
		grRecord = GetRecord(grRecord.getRecordClassName(),grRecord.sys_id);
		if (IsValidRecord(grRecord) == false)
		{
			return false;
		}
		nState = GetIntegerValue(grRecord.getValue('state'));  
		if (nCurrentState == nState)
		{
			Sleep(nSleepForSeconds);
		}
	}

	return false;
}
